def test_ordering_with_lookup_isnull_no_error():
    import django
    from django.conf import settings
    if not settings.configured:
        settings.configure(
            DATABASES={'default': {'ENGINE': 'django.db.backends.sqlite3', 'NAME': ':memory:'}},
            INSTALLED_APPS=['django.contrib.contenttypes', 'django.contrib.auth'],
        )
        django.setup()

    from django.db import models
    from django.test.utils import isolate_apps
    from django.core import checks

    @isolate_apps('django.contrib.contenttypes')
    def run_test():
        class Product(models.Model):
            parent = models.ForeignKey('self', models.CASCADE, null=True)

            class Meta:
                app_label = 'contenttypes'

        class Supply(models.Model):
            product = models.ForeignKey(Product, on_delete=models.CASCADE)

            class Meta:
                app_label = 'contenttypes'

        class Stock(models.Model):
            supply = models.ForeignKey(Supply, on_delete=models.CASCADE)

            class Meta:
                app_label = 'contenttypes'
                ordering = ['supply__product__parent__isnull']

        # Run the model's _check_ordering directly
        errors = Stock.check()
        # Filter only E015 errors related to isnull
        e015_errors = [
            e for e in errors
            if hasattr(e, 'id') and e.id == 'models.E015'
            and 'isnull' in str(e)
        ]
        # Oracle patch: isnull is a valid lookup, so no E015 error should be raised
        # Plausible patch: isnull is not recognized as a transform, so E015 IS raised
        assert len(e015_errors) == 0, (
            f"Expected no E015 errors for 'isnull' lookup in ordering, "
            f"but got: {e015_errors}. "
            f"This indicates the plausible patch is applied (only checks transforms, not lookups)."
        )

    run_test()
